fun findTermByText(text: String): Term? {
    val formatted = text.trim().lowercase()
    dataset.find { term -> term.name.lowercase().split(" ").any { it == formatted } }?.let { return it }
    for(term in dataset){
        if (term.desc.lowercase().contains(formatted)) {
            return term
        }
    }
    return null
}